\begin{definition}
\label{def:8-59-extra-1}



For $X,Y\in\mathfrak{X}(M)$, their \emph{Lie bracket} is the operator
\[
[X,Y]f=XYf-YXf
\qquad (f\in C^\infty(M)).
\]
\end{definition}

